plist.dict:
CFBundlePackageType
APPL
CFBundleName
{{.Info.ProductName}}
CFBundleExecutable
{{.OutputFilename}}
CFBundleIdentifier
dev.theorchestra.Orchestra
CFBundleVersion
{{.Info.ProductVersion}}
CFBundleGetInfoString
{{.Info.Comments}}
CFBundleShortVersionString
{{.Info.ProductVersion}}
CFBundleIconFile
iconfile
LSMinimumSystemVersion
13.0
NSHighResolutionCapable
true
NSHumanReadableCopyright
{{.Info.Copyright}}
NSAppleEventsUsageDescription
Orchestra allows terminal-launched developer tools to automate local apps when you request it.
NSAudioCaptureUsageDescription
Orchestra allows terminal-launched developer tools to capture desktop audio when you request it.
NSBluetoothAlwaysUsageDescription
Orchestra allows terminal-launched developer tools to access Bluetooth devices when you request it.
NSBluetoothPeripheralUsageDescription
Orchestra allows terminal-launched developer tools to access Bluetooth devices when you request it.
NSCameraUsageDescription
Orchestra allows terminal-launched developer tools to use the camera when you request it.
NSDocumentsFolderUsageDescription
Orchestra allows terminal-launched developer tools to access your Documents folder when you request it.
NSDownloadsFolderUsageDescription
Orchestra allows terminal-launched developer tools to access your Downloads folder when you request it.
NSLocalNetworkUsageDescription
Orchestra allows terminal-launched developer tools to discover and connect to local development servers when you request it.
NSLocationUsageDescription
Orchestra allows terminal-launched developer tools to access location when you request it.
NSMicrophoneUsageDescription
Orchestra allows terminal-launched developer tools to use the microphone when you request it.
{{if .Info.FileAssociations}}
CFBundleDocumentTypes

  {{range .Info.FileAssociations}}

    CFBundleTypeExtensions

      {{.Ext}}

    CFBundleTypeName
    {{.Name}}
    CFBundleTypeRole
    {{.Role}}
    CFBundleTypeIconFile
    {{.IconName}}

  {{end}}

{{end}}
{{if .Info.Protocols}}
CFBundleURLTypes

  {{range .Info.Protocols}}

        CFBundleURLName
        dev.theorchestra.{{.Scheme}}
        CFBundleURLSchemes

            {{.Scheme}}

        CFBundleTypeRole
        {{.Role}}

  {{end}}

{{end}}
